// Combine all data — match messages to accounts and brand voices
const accounts = $('Fetch All Active Accounts').first().json;
const messages = $('Fetch Unread Messages').first().json;
const voices = $('Fetch Brand Voices').first().json;

const accountsArr = Array.isArray(accounts) ? accounts : [];
const messagesArr = Array.isArray(messages) ? messages : [];
const voicesArr = Array.isArray(voices) ? voices : [];

// Group accounts by org_id
const accountsByOrg = {};
for (const acc of accountsArr) {
  if (!accountsByOrg[acc.org_id]) accountsByOrg[acc.org_id] = [];
  accountsByOrg[acc.org_id].push(acc);
}

// Group voices by org_id
const voiceByOrg = {};
for (const v of voicesArr) {
  voiceByOrg[v.org_id] = v;
}

// Build work items — only messages that have a matching active account
const workItems = [];
for (const msg of messagesArr) {
  const orgAccounts = accountsByOrg[msg.org_id] || [];
  const matchingAccount = orgAccounts.find(a => a.platform === msg.platform && a.is_active !== false);
  if (!matchingAccount) continue;

  const voice = voiceByOrg[msg.org_id] || { tone: 'professional and helpful' };

  // Prioritize: purchase_intent and complaints get auto-replied, others get queued
  const priority = ['purchase_intent', 'complaint', 'inquiry'].includes(msg.message_type) ? 'high' : 'normal';

  workItems.push({
    message_id: msg.id,
    org_id: msg.org_id,
    platform: msg.platform,
    platform_msg_id: msg.platform_msg_id,
    author_name: msg.author_name || 'there',
    message_body: msg.body,
    message_type: msg.message_type,
    account: matchingAccount,
    voice,
    priority
  });
}

// Only auto-reply high priority for now (normal → just mark read)
console.log(`[Growth Monitor] ${workItems.length} messages to process`);

return workItems.filter(w => w.priority === 'high').slice(0, 10); // max 10 per run

