// Decide whether to auto-post or queue the reply
const gptResponse = $input.first().json;
const workItem = $('Build Work Items').first().json;

let reply = '';
let confidence = 0;

try {
  const parsed = JSON.parse(gptResponse.choices[0].message.content);
  reply = parsed.reply || '';
  confidence = parsed.confidence || 0;
} catch(e) {
  return [{ skip: true, reason: 'GPT parse error' }];
}

if (!reply || confidence < 0.75) {
  // Low confidence — save as draft for human review, don't auto-post
  return [{
    skip: true,
    save_as_draft: true,
    reply,
    confidence,
    ...workItem
  }];
}

// High confidence — ready to auto-post
return [{
  skip: false,
  reply,
  confidence,
  ...workItem
}];

// Save reply as draft in Supabase for human review
const data = $input.first().json;
const supaUrl = process.env.SUPABASE_URL;
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!supaUrl || !supaKey) return [{ saved: false }];

// Insert draft reply
await $helpers.httpRequest({
  method: 'POST',
  url: `${supaUrl}/rest/v1/social_replies`,
  headers: {
    'apikey': supaKey,
    'Authorization': `Bearer ${supaKey}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: JSON.stringify({
    message_id: data.message_id,
    org_id: data.org_id,
    body: data.reply,
    status: 'draft'
  })
});

// Mark message as read
await $helpers.httpRequest({
  method: 'PATCH',
  url: `${supaUrl}/rest/v1/social_messages?id=eq.${data.message_id}`,
  headers: {
    'apikey': supaKey,
    'Authorization': `Bearer ${supaKey}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: JSON.stringify({ is_read: true, status: 'reviewed' })
});

console.log(`[Growth Monitor] Saved draft reply for message ${data.message_id} (confidence: ${data.confidence})`);
return [{ saved: true, message_id: data.message_id }];

// Build and execute the platform-specific reply
const data = $input.first().json;
const platform = data.platform;
const token = data.account.access_token;
const replyText = data.reply;
const platformMsgId = data.platform_msg_id;

let apiUrl = '';
let apiBody = {};
let extraHeaders = {};

switch (platform) {
  case 'linkedin':
    apiUrl = `https://api.linkedin.com/v2/socialActions/${encodeURIComponent(platformMsgId)}/comments`;
    apiBody = {
      actor: `urn:li:person:${data.account.account_id}`,
      message: { text: replyText }
    };
    extraHeaders = { 'Authorization': `Bearer ${token}`, 'X-Restli-Protocol-Version': '2.0.0' };
    break;

  case 'facebook':
    apiUrl = `https://graph.facebook.com/v18.0/${platformMsgId}/comments`;
    apiBody = { message: replyText, access_token: token };
    break;

  case 'instagram':
    apiUrl = `https://graph.facebook.com/v18.0/${platformMsgId}/replies`;
    apiBody = { message: replyText, access_token: token };
    break;

  case 'x':
  case 'twitter':
    apiUrl = 'https://api.twitter.com/2/tweets';
    apiBody = {
      text: replyText.slice(0, 280),
      reply: { in_reply_to_tweet_id: platformMsgId }
    };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;

  case 'tiktok':
    apiUrl = 'https://open.tiktokapis.com/v2/comment/create/';
    apiBody = { video_id: platformMsgId, text: replyText.slice(0, 150) };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;
}

// Post the reply
try {
  const result = await $helpers.httpRequest({
    method: 'POST',
    url: apiUrl,
    headers: { 'Content-Type': 'application/json', ...extraHeaders },
    body: JSON.stringify(apiBody)
  });

  const supaUrl = process.env.SUPABASE_URL;
  const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (supaUrl && supaKey) {
    // Insert sent reply record
    await $helpers.httpRequest({
      method: 'POST',
      url: `${supaUrl}/rest/v1/social_replies`,
      headers: {
        'apikey': supaKey,
        'Authorization': `Bearer ${supaKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify({
        message_id: data.message_id,
        org_id: data.org_id,
        body: replyText,
        status: 'sent',
        sent_at: new Date().toISOString()
      })
    });

    // Mark original message as replied
    await $helpers.httpRequest({
      method: 'PATCH',
      url: `${supaUrl}/rest/v1/social_messages?id=eq.${data.message_id}`,
      headers: {
        'apikey': supaKey,
        'Authorization': `Bearer ${supaKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify({ status: 'replied', is_read: true })
    });
  }

  console.log(`[Growth Monitor] Auto-replied to ${platform} message ${data.message_id}`);
  return [{ replied: true, message_id: data.message_id, platform, confidence: data.confidence }];

} catch(err) {
  console.error(`[Growth Monitor] Reply failed for ${data.message_id}: ${err.message}`);
  return [{ replied: false, error: err.message, message_id: data.message_id }];
}

// Log run summary to Supabase workflow_runs table
const supaUrl = process.env.SUPABASE_URL;
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

const allResults = $input.all().map(i => i.json);
const replied = allResults.filter(r => r.replied === true).length;
const drafted = allResults.filter(r => r.saved === true).length;
const failed = allResults.filter(r => r.replied === false).length;

console.log(`[Growth Monitor] Run complete — replied: ${replied}, drafted: ${drafted}, failed: ${failed}`);

if (supaUrl && supaKey) {
  await $helpers.httpRequest({
    method: 'POST',
    url: `${supaUrl}/rest/v1/workflow_runs`,
    headers: {
      'apikey': supaKey,
      'Authorization': `Bearer ${supaKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      workflow_type: 'growth_intelligence',
      status: 'complete',
      completed_at: new Date().toISOString(),
      output_summary: { replied, drafted, failed, timestamp: new Date().toISOString() }
    })
  });
}

return [{ replied, drafted, failed }];
